const url = "http://172.19.0.2:8181/mcp";
const headers = { "Content-Type": "application/json", "Accept": "application/json, text/event-stream" };

async function post(body, sessionId) {
  const h = { ...headers };
  if (sessionId) h["Mcp-Session-Id"] = sessionId;
  const res = await fetch(url, { method: "POST", headers: h, body: JSON.stringify(body) });
  const text = await res.text();
  return { status: res.status, headers: Object.fromEntries(res.headers.entries()), text };
}

// 1. initialize
const init = await post({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2024-11-05", capabilities: {}, clientInfo: { name: "probe", version: "1.0" } } });
const sessionId = init.headers["mcp-session-id"];

// parse SSE or JSON
function parseBody(text) {
  if (!text) return null;
  if (text.startsWith("{")) return JSON.parse(text);
  // SSE: lines like "data: {...}"
  const dataLines = text.split("\n").filter(l => l.startsWith("data:")).map(l => l.slice(5).trim());
  if (dataLines.length) return JSON.parse(dataLines[dataLines.length - 1]);
  return text;
}

// 2. initialized notification
await post({ jsonrpc: "2.0", method: "notifications/initialized" }, sessionId);

// 3. tools/list
