let summary = null;
if (parse.status === "fulfilled") {
  const v = parse.value;
  const sys = v.model.softwareSystems.find(s => s.name === "Claims Center");
  summary = {
    workspaceName: v.name,
    people: v.model.people.map(p => p.name),
    systems: v.model.softwareSystems.map(s => s.name),
    containers: sys.containers.map(c => c.name),
    containerCount: sys.containers.length,
    relationships: sys.containers.flatMap(c => (c.relationships || []).map(r => `${c.name} -> ${r.description} [${r.technology}]`)),
    systemLevelRelationships: (sys.relationships || []).map(r => `ClaimsCenter -> ${r.description} [${r.technology}]`),
    views: {
      systemContext: (v.views.systemContextViews || []).map(x => ({ key: x.key, elements: x.elements.length, relationships: x.relationships.length })),
      container: (v.views.containerViews || []).map(x => ({ key: x.key, elements: x.elements.length, relationships: x.relationships.length })),
    },
  };
}
return JSON.stringify({ validate: fmt(validate), inspect: fmt(inspect), summary }, null, 2);

